# ============================================================
#  EcoGuardHQ — Apply All Bug Fixes & Push to GitHub
#  Run from the ROOT of your repo:  .\apply_fixes.ps1
#  PowerShell 5.1+  |  Git must be in PATH
# ============================================================
$CommitMsg = "fix: apply full-stack bug fixes (29 issues resolved)"
$Branch    = "main"
$NoPush    = $true

$ErrorActionPreference = "Stop"
$Root = Split-Path -Parent $MyInvocation.MyCommand.Path

function Write-Step($msg) {
    Write-Host ""
    Write-Host "  --> $msg" -ForegroundColor Cyan
}
function Write-Ok($msg)   { Write-Host "  [OK] $msg"    -ForegroundColor Green }
function Write-Warn($msg) { Write-Host "  [!!] $msg"    -ForegroundColor Yellow }

Write-Host ""
Write-Host "============================================" -ForegroundColor Green
Write-Host "  EcoGuardHQ Bug Fix Applicator" -ForegroundColor White
Write-Host "============================================" -ForegroundColor Green
Write-Host ""

# Verify we're in a git repo
# (git check removed — script works with or without a git repo)

Set-Location $Root
Write-Ok "Working directory: $Root"


# ── dashboard/src/components/ControlCenter.tsx ──
Write-Step "Writing dashboard/src/components/ControlCenter.tsx"
$destDir = Join-Path $Root "dashboard\src\components"
if (-not (Test-Path $destDir)) { New-Item -ItemType Directory -Force -Path $destDir | Out-Null }
