[System.IO.File]::WriteAllBytes(
    (Join-Path $Root "dashboard_api.py"),
    [Convert]::FromBase64String(($b64_dashboard_api_py -replace "`r`n|`n|`r", ""))
)
Write-Ok "  dashboard_api.py"


# ── Delete App.css (dead Vite scaffold) ──
Write-Step "Removing dead file: dashboard/src/App.css"
$appCss = Join-Path $Root "dashboard\src\App.css"
if (Test-Path $appCss) {
    Remove-Item $appCss -Force
    Write-Ok "  App.css deleted"
} else {
    Write-Ok "  App.css already gone"
}

# ── Git: stage, commit, push ──
Write-Step "Staging all changes"
git add -A
Write-Ok "  git add -A done"

Write-Step "Committing"
$status = git status --porcelain
if (-not $status) {
    Write-Warn "Nothing to commit — all fixes already applied."
} else {
    git commit -m $CommitMsg
    Write-Ok "  Committed: $CommitMsg"
}

if ($NoPush) {
    Write-Warn "-NoPush flag set — skipping git push"
} else {
    Write-Step "Pushing to origin/$Branch"
    git push origin $Branch
    Write-Ok "  Pushed to origin/$Branch"
}

Write-Host ""
Write-Host "============================================" -ForegroundColor Green
Write-Host "  All fixes applied successfully!" -ForegroundColor Green
Write-Host "============================================" -ForegroundColor Green
Write-Host ""
Write-Host "  Files changed (13):" -ForegroundColor White
Write-Host "    dashboard/src/components/ControlCenter.tsx"
Write-Host "    dashboard/src/components/Sidebar.tsx"
Write-Host "    dashboard/src/components/MaintenanceForecast.tsx"
Write-Host "    dashboard/src/components/WaterGauge.tsx"
Write-Host "    dashboard/src/components/Dashboard.tsx"
Write-Host "    dashboard/src/components/DistributionView.tsx"
Write-Host "    dashboard/src/components/asaase/ControlHub.tsx"
Write-Host "    dashboard/src/components/asaase/AsaaseView.tsx"
Write-Host "    dashboard/src/components/asaase/AlertList.tsx"
Write-Host "    dashboard/src/components/asaase/ReportViewer.tsx"
Write-Host "    dashboard/src/asaaseApi.ts"
Write-Host "    dashboard/src/index.css"
Write-Host "    dashboard_api.py"
Write-Host "    dashboard/src/App.css  (deleted)"
Write-Host ""
Write-Host "  Next: python dashboard_api.py  +  cd dashboard && npm run dev" -ForegroundColor Cyan
Write-Host ""